use std::time::Duration;

use prometheus::{Histogram, HistogramOpts, IntCounter, Registry};

/// Buckets in seconds, from 5 ms to 1 s, as the dashboards' panels expect.
const BUCKETS: [f64; 8] = [0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1.0];

/// The name the dashboards query.
const LATENCY: &str = "replay_latency_seconds";
/// What the server exported before, kept as an alias for one release.
const LATENCY_WAS: &str = "history_replay_ms";

pub struct ReplayMetrics {
    latency: Histogram,
    alias: Histogram,
    requests: IntCounter,
    errors: IntCounter,
}

impl ReplayMetrics {
    pub fn register(registry: &Registry) -> prometheus::Result<Self> {
        let latency = histogram(LATENCY, "How long a history replay took")?;
        let alias = histogram(LATENCY_WAS, "Deprecated: use replay_latency_seconds")?;
        let requests = IntCounter::new("replay_requests_total", "History replays asked for")?;
        let errors = IntCounter::new("replay_errors_total", "History replays that failed")?;
        registry.register(Box::new(latency.clone()))?;
        registry.register(Box::new(alias.clone()))?;
        registry.register(Box::new(requests.clone()))?;
        registry.register(Box::new(errors.clone()))?;
        Ok(Self { latency, alias, requests, errors })
    }

    pub fn replayed(&self, took: Duration) {
        self.requests.inc();
        self.latency.observe(took.as_secs_f64());
        self.alias.observe(took.as_secs_f64() * 1000.0);
    }

    pub fn failed(&self) {
        self.errors.inc();
    }
}

fn histogram(name: &str, help: &str) -> prometheus::Result<Histogram> {
    Histogram::with_opts(HistogramOpts::new(name, help).buckets(BUCKETS.to_vec()))
}
